import test from 'node:test';
import assert from 'node:assert/strict';
import {spawn} from 'node:child_process';
import {mkdtemp, writeFile, readFile, rm} from 'node:fs/promises';
import {tmpdir} from 'node:os';
import {fileURLToPath} from 'node:url';
import {testServer} from '../../server/test/helpers.js';

async function scenario(fn) {
  const server = await testServer();
  const directory = await mkdtemp(tmpdir() + '/crew-search-cli-');
  try {
    const api = server.agent();
    await api('POST', '/auth/signup', {name: 'Search CLI', email: 'searchcli@example.test', password: 'correct-horse-battery'});
    const org = (await api('POST', '/orgs', {name: 'CLI search'})).data.organization;
    const project = (await api('POST', '/orgs/' + org.id + '/projects', {key: 'CLI', name: 'CLI search project'})).data.project;
    const token = (await api('POST', '/tokens', {name: 'CLI', scopes: ['*']})).data.token;
    await writeFile(directory + '/config.json', JSON.stringify({url: server.url, token}), {mode: 0o600});
    const cli = args => new Promise((resolve, reject) => {
      const child = spawn(process.execPath, [fileURLToPath(new URL('../bin/crew.js', import.meta.url)), ...args, '--config', directory + '/config.json', '--json']);
      let stdout = '', stderr = '';
      const timer = setTimeout(() => {child.kill('SIGKILL'); reject(new Error('CLI deadline exceeded'));}, 10000);
      child.stdout.on('data', value => stdout += value);
      child.stderr.on('data', value => stderr += value);
      child.on('error', error => {clearTimeout(timer); reject(error);});
      child.on('close', code => {
        clearTimeout(timer);
        let data = null;
        try {if (stdout.trim()) data = /^[{[]/.test(stdout.trim()) ? JSON.parse(stdout) : stdout.trim();} catch (error) {reject(error); return;}
        resolve({code, data, stdout, stderr});
      });
    });
    await fn({server, api, org, project, cli, directory});
  } finally {await server.close(); await rm(directory, {recursive: true, force: true});}
}

test('actual token CLI searches compound queries and traverses all cursor pages', () => scenario(async ({api, org, project, cli}) => {
  for (const title of ['Search first', 'Search second', 'Search third']) await api('POST', '/projects/' + project.id + '/issues', {title, priority: 3});
  const result = await cli(['search', '--org', org.id, '--query', 'search AND priority>=3', '--limit', '1', '--all']);
  assert.equal(result.code, 0, result.stderr);
  assert.equal(result.data.items.length, 3);
  assert.equal(result.data.nextCursor, null);
}));
test('actual CLI validates queries locally and gets accessible suggestions', () => scenario(async ({cli, org}) => {
  const checked = await cli(['search', 'check', 'assignee:@me AND NOT status:done']);
  assert.equal(checked.code, 0, checked.stderr); assert.equal(checked.data.valid, true);
  assert.equal((await cli(['search', 'check', 'label:'])).code, 1);
  const suggestions = await cli(['search', 'suggest', 'project:', '--org', org.id]);
  assert.equal(suggestions.code, 0, suggestions.stderr);
  assert.equal(suggestions.data.items[0].replacement, 'project:CLI');
}));
test('actual CLI creates edits runs and confirms deletion of saved filters', () => scenario(async ({api, cli, org, project, directory}) => {
  await api('POST', '/projects/' + project.id + '/issues', {title: 'Important', priority: 4});
  await writeFile(directory + '/query.txt', 'priority>=3');
  const created = await cli(['filter', 'create', '--org', org.id, '--name', 'Urgent', '--query-file', directory + '/query.txt']);
  assert.equal(created.code, 0, created.stderr);
  const id = created.data.filter.id;
  assert.equal((await cli(['filter', 'run', id])).data.total, 1);
  const edited = await cli(['filter', 'edit', id, '--name', 'Critical', '--query', 'priority>=4', '--revision', '1']);
  assert.equal(edited.code, 0, edited.stderr); assert.equal(edited.data.filter.revision, 2);
  assert.equal((await cli(['filter', 'edit', id, '--name', 'Stale', '--revision', '1'])).code, 1);
  assert.equal((await cli(['filter', 'delete', id])).code, 1);
  assert.equal((await cli(['filter', 'delete', id, '--yes'])).code, 0);
  assert.equal((await cli(['filter', 'show', id])).code, 1);
}));
test('actual CLI lists saved filters and documents every search family', () => scenario(async ({cli, org}) => {
  await cli(['filter', 'create', '--org', org.id, '--name', 'Everything']);
  const list = await cli(['filter', 'list', '--org', org.id]);
  assert.equal(list.code, 0, list.stderr); assert.equal(list.data.items[0].name, 'Everything');
  const options = await cli(['filter', 'options', '--org', org.id]);
  assert.equal(options.code, 0, options.stderr); assert.equal(options.data.projects.length, 1);
  assert.equal((await cli(['search', '--help'])).code, 0);
  assert.equal((await cli(['filter', '--help'])).code, 0);
}));

test('actual CLI owned false includes a visible teammate filter while true includes only mine', () => scenario(async ({server, api, cli, org}) => {
  const mine = (await api('POST', '/filters', {orgId: org.id, name: 'My personal filter'})).data.filter;
  const peer = server.agent();
  const person = (await peer('POST', '/auth/signup', {name: 'Teammate', email: 'owned-peer@example.test', password: 'correct-horse-battery'})).data.user;
  await api('POST', '/orgs/' + org.id + '/members', {userId: person.id, role: 'member'});
  const team = (await api('POST', '/orgs/' + org.id + '/teams', {name: 'Filter readers'})).data.team;
  for (const userId of [mine.ownerId, person.id]) await api('POST', '/teams/' + team.id + '/members', {userId});
  const shared = (await peer('POST', '/filters', {orgId: org.id, name: 'Peer shared filter', visibility: 'team', teamId: team.id})).data.filter;
  const own = await cli(['filter', 'list', '--org', org.id, '--owned', 'true']);
  const visible = await cli(['filter', 'list', '--org', org.id, '--owned', 'false']);
  assert.equal(own.code, 0, own.stderr); assert.equal(visible.code, 0, visible.stderr);
  assert.deepEqual(own.data.items.map(row => row.id), [mine.id]);
  assert.deepEqual(new Set(visible.data.items.map(row => row.id)), new Set([mine.id, shared.id]));
  assert.equal(visible.data.items.find(row => row.id === shared.id).canEdit, false);
  assert.deepEqual((await cli(['filter', 'list', '--org', org.id, '--owned=false'])).data.items, visible.data.items);
  await api('DELETE', '/teams/' + team.id + '/members/' + mine.ownerId);
  assert.deepEqual((await cli(['filter', 'list', '--org', org.id, '--owned=false'])).data.items.map(row => row.id), [mine.id]);
}));
test('actual CLI rejects invalid or missing owned values with explicit help', () => scenario(async ({cli, org}) => {
  for (const value of ['yes', '1', 'TRUE', '']) {
    const result = await cli(['filter', 'list', '--org', org.id, '--owned=' + value]);
    assert.equal(result.code, 1); assert.match(result.stderr, /Expected one of true, false/);
  }
  const missing = await cli(['filter', 'list', '--org', org.id, '--owned']);
  assert.equal(missing.code, 1); assert.match(missing.stderr, /Missing value for --owned/);
  assert.match((await cli(['filter', '--help'])).stdout, /--owned true\|false/);
}));
test('actual CLI owned list obeys current token scope and revocation', () => scenario(async ({api, cli, org, directory}) => {
  const saved = (await api('POST', '/filters', {orgId: org.id, name: 'Scoped ownership'})).data.filter;
  const minted = await api('POST', '/tokens', {name: 'Filter read only', scopes: ['insight:read']});
  const current = JSON.parse(await readFile(directory + '/config.json', 'utf8'));
  await writeFile(directory + '/config.json', JSON.stringify({...current, token: minted.data.token}), {mode: 0o600});
  assert.equal((await cli(['filter', 'list', '--org', org.id, '--owned=false'])).data.items[0].id, saved.id);
  assert.equal((await cli(['filter', 'edit', saved.id, '--name', 'Denied change'])).code, 1);
  const tokens = await api('GET', '/tokens');
  const token = tokens.data.items.find(row => row.name === 'Filter read only');
  assert.ok(token); await api('DELETE', '/tokens/' + token.id);
  assert.equal((await cli(['filter', 'list', '--org', org.id, '--owned=false'])).code, 1);
  assert.equal((await api('GET', '/filters/' + saved.id)).data.filter.name, 'Scoped ownership');
}));

import {useEffect, useLayoutEffect, useRef, useState} from 'preact/hooks';
import {Page, Field, Button, Notice, Empty, Loading, useLoad, ConfirmButton} from '../../components/ui.jsx';
import {routeLink} from '../../router.js';
import {filterView, filterViewLocation} from './filter-view.js';
import {EntityPicker} from './selectors.jsx';
import {FilterForm} from './filter-form.jsx';
import {useScopedLoad} from './scoped-load.js';
import {createRequestGuard} from './request-guard.js';
import {createPlanningScope} from '../work/planning-actions.js';

export function FiltersPage(props) {
  const owner = useRef({generation: 0});
  const predecessors = useRef(new Map()).current;
  let view, error;
  try {view = filterView(props.query);} catch (failure) {error = failure;}
  const identity = view ? filterViewLocation(view) : JSON.stringify(props.query);
  if (owner.current.api !== props.api) predecessors.clear();
  if (owner.current.api !== props.api || owner.current.identity !== identity) owner.current = {api: props.api, identity, generation: owner.current.generation + 1};
  if (error) return <Page title="Saved filters"><Notice error={error}/><a href={routeLink('/filters')}>Reset invalid saved-filter view</a></Page>;
  return <FiltersOrganization key={owner.current.generation} {...props} view={view} predecessors={predecessors}/>;
}
function FiltersOrganization({api, view, navigate, predecessors}) {
  const organizations = useLoad(() => api.get('/insight/options?type=organizations&limit=1'), []);
  const orgId = view.orgId;
  const discardRef = useRef(() => true);
  const [pickerVersion, setPickerVersion] = useState(0);
  useEffect(() => {if (!orgId && organizations.data?.items.length) navigate(filterViewLocation({...view, orgId: organizations.data.items[0].id}));}, [organizations.data]);
  function changeOrg(value) {
    if (value === orgId) return;
    if (discardRef.current()) navigate(filterViewLocation({orgId: value})); else setPickerVersion(version => version + 1);
  }
  return <Page title="Saved filters" actions={<a href={routeLink('/search', {orgId})} onClick={event => {if (!discardRef.current()) event.preventDefault();}}>Search issues</a>}>
    <Notice error={organizations.error}/>
    {organizations.loading ? <Loading/> : !organizations.data?.items.length ? <Empty>Join an organization before saving a filter.</Empty> : <>
      <EntityPicker key={pickerVersion} api={api} type="organizations" label="Organization" value={orgId} required onChange={changeOrg}/>
      <FiltersScope api={api} view={view} discardRef={discardRef} navigate={navigate} predecessors={predecessors}/>
    </>}
  </Page>;
}
function FiltersScope({api, view, discardRef, navigate, predecessors}) {
  const {orgId, cursor} = view;
  const location = filterViewLocation(view);
  const [draft, setDraft] = useState({...view, cursor: ''});
  const [editing, setEditing] = useState(null);
  const [error, setError] = useState(null);
  const [message, setMessage] = useState('');
  const [busy, setBusy] = useState(false);
  const [opening, setOpening] = useState('');
  const [hidden, setHidden] = useState(() => new Set());
  const editor = useRef(null);
  const alive = useRef(true);
  const pendingEdit = useRef(null);
  const editGuard = useRef(createRequestGuard()).current;
  const mutations = useRef(createPlanningScope()).current;
  const options = useScopedLoad(orgId, () => orgId ? api.get('/filters/options?orgId=' + encodeURIComponent(orgId)) : {teams: []});
  const listing = useScopedLoad(location, () => orgId ? api.get('/filters?' + new URLSearchParams({...view, limit: '25'})) : {items: [], total: 0});
  useLayoutEffect(() => () => {alive.current = false; editor.current = null; editGuard.invalidate(); mutations.dispose(); discardRef.current = () => true;}, []);
  function hide(id) {setHidden(previous => new Set([...previous, id]));}
  const visibleItems = listing.data?.items.filter(filter => !hidden.has(filter.id)) ?? [];
  function setEditor(value) {editor.current = value; setEditing(value);}
  function replaceEditor(value) {
    if (!discardRef.current()) return;
    editGuard.invalidate(); pendingEdit.current = null; setOpening(''); setEditor(value);
  }
  async function remove(filter) {
    const operation = mutations.begin();
    if (!operation) return;
    editGuard.invalidate(); pendingEdit.current = null; setOpening('');
    setError(null); setBusy(true);
    try {
      await api.delete('/filters/' + encodeURIComponent(filter.id), undefined, {signal: operation.signal});
      if (!operation.current()) return;
      hide(filter.id); if (editor.current?.id === filter.id) setEditor(null);
      setMessage('Deleted “' + filter.name + '”.'); listing.reload();
    } catch (failure) {if (operation.current()) {setError(failure); if ([401, 403, 404].includes(failure.status)) {hide(filter.id); listing.reload();}}}
    finally {if (operation.current()) {setBusy(false); operation.finish();}}
  }
  async function edit(filter) {
    if (pendingEdit.current === filter.id || !discardRef.current()) return;
    setEditor(null); setError(null); pendingEdit.current = filter.id; setOpening(filter.name);
    const ticket = editGuard.begin();
    try {
      const result = await api.get('/filters/' + encodeURIComponent(filter.id), {signal: ticket.signal});
      if (editGuard.current(ticket)) setEditor(result.filter);
    } catch (failure) {if (editGuard.current(ticket)) {setError(failure); if ([401, 403, 404].includes(failure.status)) {hide(filter.id); listing.reload();}}}
    finally {if (editGuard.current(ticket)) {pendingEdit.current = null; setOpening('');}}
  }
  function follow(event) {if (!discardRef.current()) event.preventDefault();}
  function go(input, previous) {
    let next, applied;
    try {applied = filterView(input); next = filterViewLocation(applied);} catch (failure) {setError(failure); return;}
    if (!discardRef.current()) return;
    if (previous !== undefined) predecessors.set(next, previous);
    setError(null);
    if (next === location) {setDraft({...applied, cursor: ''}); listing.reload(); return;}
    alive.current = false; editGuard.invalidate(); mutations.dispose();
    navigate(next);
  }
  function apply(event) {event.preventDefault(); go(draft);}
  const update = (field, value) => setDraft(previous => ({...previous, [field]: value}));
  const unsent = ['q', 'visibility', 'teamId', 'owned'].some(field => draft[field] !== view[field]);
  return <>
    <Notice error={error ?? listing.error ?? options.error}/><Notice>{message}</Notice>
    {opening && <Notice>Opening “{opening}”…</Notice>}
    <form className="search-controls" aria-label="Saved-filter view" onSubmit={apply}>
      <Field label="Find a saved filter"><input value={draft.q} maxLength={100} placeholder="Name or description" onInput={event => update('q', event.currentTarget.value)}/></Field>
      <Field label="Visibility"><select value={draft.visibility} onChange={event => update('visibility', event.currentTarget.value)}>
        <option value="all">Personal and shared</option><option value="personal">Personal</option><option value="team">Team shared</option>
      </select></Field>
      <Field label="Team"><select value={draft.teamId} onChange={event => update('teamId', event.currentTarget.value)}>
        <option value="">All my teams</option>{options.data?.teams.map(team => <option key={team.id} value={team.id}>{team.name}</option>)}
      </select></Field>
      <label><input type="checkbox" checked={draft.owned === 'true'} onChange={event => update('owned', String(event.currentTarget.checked))}/>Created by me</label>
      <p role="status">{unsent ? 'View changes are not applied. Apply to start at the first page.' : 'Showing the applied view from this URL.'}</p>
      <Button type="submit" disabled={!orgId || busy}>Apply view</Button>
      <Button type="button" disabled={!orgId || busy} onClick={() => go({orgId})}>Reset view</Button>
    </form>
    <p>Copy the current URL to reopen this applied view and page. Browser Back, Forward or reload can replace local unsaved drafts.</p>
    <Button disabled={!orgId || busy || listing.loading} onClick={listing.reload}>Refresh filters</Button>
    <Button disabled={!orgId || busy || Boolean(options.error)} onClick={() => replaceEditor({})}>Create saved filter</Button>
    {editing && <FilterForm api={api} orgId={orgId} filter={editing} teams={options.data?.teams} discardRef={discardRef}
      onCancel={() => setEditor(null)} onUnavailable={() => {if (editing.id) hide(editing.id); listing.reload();}} onSaved={filter => {
        if (!alive.current || editor.current !== editing) return;
        setEditor(null); setMessage('Saved “' + filter.name + '”.'); listing.reload();
      }}/>}
    {listing.loading ? <Loading/> : listing.error ? null : !visibleItems.length ? <Empty>No saved filters in this view. Create one or ask a teammate to share one.</Empty> : <>
      <p>{listing.data.total} accessible filters</p>
      <ul className="saved-filters">{visibleItems.map(filter => <li key={filter.id}>
        <article><h2><a href={routeLink('/filters/' + encodeURIComponent(filter.id), {returnTo: location})} onClick={follow}>{filter.name}</a></h2>
          {filter.description && <p>{filter.description}</p>}<p>Updated {new Date(filter.updatedAt).toLocaleString()}</p>
          <pre>{filter.query || 'All accessible issues'}</pre>
          <p>{filter.visibility === 'personal' ? 'Personal' : 'Team: ' + (options.data?.teams.find(team => team.id === filter.teamId)?.name ?? 'Shared team')} · revision {filter.revision}</p>
          <div className="actions"><a className="button" href={routeLink('/filters/' + encodeURIComponent(filter.id), {run: '1', returnTo: location})} onClick={follow}>Run filter</a>
            {filter.canEdit && <><Button disabled={busy} onClick={() => edit(filter)}>Edit</Button>
              <ConfirmButton disabled={busy} message={'Delete saved filter “' + filter.name + '”?'} onConfirm={() => {if (discardRef.current()) remove(filter);}}>Delete</ConfirmButton></>}
          </div>
        </article>
      </li>)}</ul>
    </>}
    <div className="actions">
      <Button disabled={busy || !cursor} onClick={() => go({...view, cursor: ''})}>First page</Button>
      <Button disabled={busy || !predecessors.has(location)} onClick={() => go({...view, cursor: predecessors.get(location)})}>Previous</Button>
      <span>{cursor ? 'Later page' : 'First page'}</span>
      <Button disabled={busy || listing.loading || !listing.data?.nextCursor} onClick={() => go({...view, cursor: listing.data.nextCursor}, cursor)}>Next</Button>
    </div>
    {cursor && !predecessors.has(location) && <p>The previous page is unavailable after opening this URL. Use First page, or browser Back to revisit a known view.</p>}
  </>;
}

import json, signal, sys
from urllib.parse import urlparse, parse_qs, urlencode
from selenium import webdriver
from selenium.webdriver.chrome.service import Service
from selenium.webdriver.common.by import By
from selenium.webdriver.common.keys import Keys
from selenium.webdriver.support.ui import WebDriverWait, Select
from selenium.webdriver.support import expected_conditions as EC
s = json.loads(sys.argv[1]); driver = None
signal.signal(signal.SIGALRM, lambda *args: (_ for _ in ()).throw(TimeoutError('Saved-filter view browser exceeded 25 seconds'))); signal.alarm(25)
try:
    options = webdriver.ChromeOptions(); options.binary_location = '/usr/bin/chromium'
    options.set_capability('goog:loggingPrefs', {'browser': 'ALL'})
    for flag in ['--headless=new', '--no-sandbox', '--disable-dev-shm-usage', '--window-size=1440,1400']: options.add_argument(flag)
    driver = webdriver.Chrome(service=Service('/usr/bin/chromedriver'), options=options); driver.set_page_load_timeout(8); wait = WebDriverWait(driver, 6)
    driver.get(s['url']); name, value = s['cookie'].split('=', 1); driver.add_cookie({'name': name, 'value': value, 'path': '/'})
    driver.execute_cdp_cmd('Page.addScriptToEvaluateOnNewDocument', {'source': """
      window.__nativeFetch=fetch.bind(window);window.__requests=[];window.__held=[];window.__events=[];
      for(const type of ['submit','invalid','click'])document.addEventListener(type,event=>window.__events.push({type,target:event.target.outerHTML?.slice(0,200),fields:[...document.querySelectorAll('.filter-form input,.filter-form textarea,.filter-form select')].map(el=>({value:el.value,valid:el.validity.valid}))}),true);
      window.fetch=(url,options={})=>{
        const parsed=new URL(url,location.href),method=options.method||'GET';
        const entry={url:String(url),path:parsed.pathname,method,hasSignal:Boolean(options.signal)};
        window.__requests.push(entry);
        const hold=window.__hold&&window.__hold.path===parsed.pathname&&window.__hold.method===method&&(!window.__hold.q||parsed.searchParams.get('q')===window.__hold.q);
        if(hold)window.__hold=null;
        return window.__nativeFetch(url,options).then(async response=>{
          entry.status=response.status;if(!hold)return response;
          const bytes=await response.arrayBuffer();return new Promise(resolve=>window.__held.push({release:()=>resolve(new Response(bytes,{status:response.status,headers:response.headers}))}));
        });
      };
    """})
    def text(): return driver.find_element(By.TAG_NAME, 'body').text
    def location(): return driver.execute_script('return location.hash.slice(1)')
    def button(label, parent=None):
        xpath = './/button[normalize-space()="' + label + '"]' if parent else '//main//button[normalize-space()="' + label + '"]'
        return wait.until(lambda d: (parent or d).find_element(By.XPATH, xpath) if (parent or d).find_element(By.XPATH, xpath).is_enabled() else False)
    def write(selector, value):
        field = wait.until(EC.element_to_be_clickable((By.CSS_SELECTOR, selector))); field.send_keys(Keys.CONTROL, 'a', Keys.NULL, Keys.BACKSPACE)
        if value: field.send_keys(value)
        return field
    def names(): return driver.execute_script('return [...document.querySelectorAll(".saved-filters h2 a")].map(el=>el.textContent)')
    def page(count):
        def ready(d):
            snapshot = d.execute_script('const form=document.querySelector(\'form[aria-label="Saved-filter view"]\');const refresh=[...document.querySelectorAll("main button")].find(el=>el.textContent==="Refresh filters");return {names:[...document.querySelectorAll(".saved-filters h2 a")].map(el=>el.textContent),q:form?.querySelector("input")?.value,ready:Boolean(refresh&&!refresh.disabled)}')
            return snapshot['ready'] and len(snapshot['names']) == count and snapshot['q'] == query().get('q', [''])[0] and 'Showing the applied view from this URL.' in text()
        return wait.until(ready)
    def view_form(): return driver.find_element(By.CSS_SELECTOR, 'form[aria-label="Saved-filter view"]')
    def apply(): button('Apply view').click()
    def fields():
        form = view_form()
        return {'q': form.find_element(By.TAG_NAME, 'input').get_attribute('value'), 'visibility': form.find_elements(By.TAG_NAME, 'select')[0].get_attribute('value'), 'teamId': form.find_elements(By.TAG_NAME, 'select')[1].get_attribute('value'), 'owned': form.find_element(By.CSS_SELECTOR, 'input[type=checkbox]').is_selected()}
    def query(): return parse_qs(location().partition('?')[2])
    def api(method, path, body=None):
        return driver.execute_async_script("const [method,path,body,done]=arguments;window.__nativeFetch('/api/v1'+path,{method,headers:{'content-type':'application/json','X-Crew-Request':'1'},body:body==null?undefined:JSON.stringify(body)}).then(async r=>done({status:r.status,data:await r.json()})).catch(e=>done({error:e.message}))", method, path, body)
    def card(name): return wait.until(EC.presence_of_element_located((By.XPATH, '//ul[@class="saved-filters"]/li[.//h2/a[normalize-space()="' + name + '"]]')))
    def hold(method, path, q=None): driver.execute_script('window.__hold={method:arguments[0],path:arguments[1],q:arguments[2]};window.__held=[]', method, '/api/v1' + path, q)
    def held(): wait.until(lambda d: d.execute_script('return window.__held.length') == 1)
    def release(): driver.execute_async_script('const done=arguments[0];window.__held.splice(0).forEach(item=>item.release());requestAnimationFrame(()=>requestAnimationFrame(done))')
    def details(): wait.until(EC.presence_of_element_located((By.CSS_SELECTOR, 'article[aria-label="Saved filter details"]')))
    def return_link(): return driver.find_element(By.XPATH, '//main//a[normalize-space()="Saved filters"]')
    def current_later():
        page(25); button('Next').click(); page(5)
        assert query().get('cursor') and 'Later page' in text()
        return location(), names()
    initial = '/filters?' + urlencode({'orgId': s['orgId'], 'q': 'needle', 'visibility': 'team', 'teamId': s['teamId'], 'owned': 'true'})
    driver.get(s['url'] + '/?saved-view-proof=' + s['mode'] + '#' + initial)
    page(25)
    if s['mode'] == 'view':
